"""CARLA-lazy lane selection and route targets for exact C147331 cases.

The selected route has two same-direction adjacent driving lanes, observed
markings and no junction waypoint. A Native run must verify physical coverage.
"""

from __future__ import annotations

from math import atan2, hypot, isfinite, pi


CASE_SUFFIXES = ("within_marked_lane", "unexcused_boundary_crossing",
                 "passing_boundary_crossing", "passing_excursion-0000",
                 "passing_excursion-0001", "passing_excursion-0002")


def _xy(location):
    result = (float(location.x), float(location.y))
    if not all(isfinite(value) for value in result):
        raise ValueError("Nonfinite Native waypoint")
    return result


def _marked(waypoint):
    left = getattr(waypoint, "left_lane_marking", None)
    right = getattr(waypoint, "right_lane_marking", None)
    return all(marking is not None and
               str(marking.type).rsplit(".", 1)[-1].lower() != "none"
               for marking in (left, right))


def _driving(waypoint):
    return waypoint is not None and "driving" in str(waypoint.lane_type).lower()


def _same_lane(a, b):
    return (b is not None and int(b.road_id) == int(a.road_id)
            and int(b.lane_id) == int(a.lane_id))


def _chain(start, steps, spacing_m):
    chain = [start]
    current = start
    for _ in range(steps):
        options = [nxt for nxt in current.next(spacing_m) if _same_lane(current, nxt)]
        if len(options) != 1:
            raise ValueError("Selected Native lane has no unique connected continuation")
        current = options[0]
        if current.is_junction or not _marked(current):
            raise ValueError("Selected Native lane loses markings or enters junction")
        chain.append(current)
    return chain


def select_marked_one_way_pair(carla_map, *, spacing_m=2.0, steps=15,
                               candidate_index=0):
    """Select a deterministic marked straight route with same-direction pair.

    Road-level absence of opposite-sign driving lane IDs is an engineering
    one-way screen, not a claim about jurisdiction or all connected segments.
    """
    waypoints = list(carla_map.generate_waypoints(spacing_m))
    road_signs = {}
    for wp in waypoints:
        if _driving(wp):
            road_signs.setdefault(int(wp.road_id), set()).add(1 if wp.lane_id > 0 else -1)
    candidates = []
    for start in waypoints:
        if not _driving(start) or start.is_junction or not _marked(start):
            continue
        if int(start.lane_id) == 0 or len(road_signs.get(int(start.road_id), ())) != 1:
            continue
        neighbors = [neighbor for neighbor in (start.get_left_lane(), start.get_right_lane())
                     if _driving(neighbor) and int(neighbor.road_id) == int(start.road_id)
                     and int(neighbor.lane_id) * int(start.lane_id) > 0
                     and _marked(neighbor) and not neighbor.is_junction]
        if not neighbors:
            continue
        try:
            primary = _chain(start, steps, spacing_m)
            adjacent = _chain(neighbors[0], steps, spacing_m)
        except ValueError:
            continue
        if any(int(a.road_id) != int(b.road_id) or
               int(a.lane_id) * int(b.lane_id) <= 0
               for a, b in zip(primary, adjacent)):
            continue
        candidates.append((start, primary, adjacent))
    if not candidates:
        raise ValueError("No connected marked one-way multilane route found")
    candidates.sort(key=lambda item: (int(item[0].road_id), abs(int(item[0].lane_id)),
                                      int(item[0].lane_id),
                                      *_xy(item[0].transform.location)))
    if type(candidate_index) is not int or candidate_index < 0 or candidate_index >= len(candidates):
        raise ValueError("Requested marked route candidate is unavailable")
    start, primary, adjacent = candidates[candidate_index]
    return {"road_id": int(start.road_id), "lane_id": int(start.lane_id),
            "adjacent_lane_id": int(adjacent[0].lane_id),
            "primary": primary, "adjacent": adjacent}


def route_targets(selection, case_suffix, *, crossing_fraction=0.6):
    """Compute route-relative body-center targets and optional passing spawn.

    The fraction is an engineering path request; saved body-footprint evidence
    decides whether crossing actually occurred. It is not a legal threshold.
    """
    if case_suffix not in CASE_SUFFIXES:
        raise ValueError("Unknown exact lane case")
    if not (isfinite(crossing_fraction) and 0 < crossing_fraction < 1):
        raise ValueError("Invalid crossing construction fraction")
    primary = selection["primary"]
    adjacent = selection["adjacent"]
    if len(primary) != len(adjacent) or len(primary) < 4:
        raise ValueError("Matched adjacent Native route samples required")
    route = []
    for index, (base, neighbor) in enumerate(zip(primary, adjacent)):
        a, b = _xy(base.transform.location), _xy(neighbor.transform.location)
        if hypot(a[0] - b[0], a[1] - b[1]) <= 0:
            raise ValueError("Adjacent Native lane centers coincide")
        fraction = 0.0 if case_suffix == "within_marked_lane" else (
            crossing_fraction if index >= len(primary) // 2 else 0.0)
        route.append([a[0] + fraction * (b[0] - a[0]),
                      a[1] + fraction * (b[1] - a[1])])
    return {"case_suffix": case_suffix, "targets_xy_m": route,
            "overtaken_spawn": primary[len(primary) // 2].transform
            if case_suffix == "passing_boundary_crossing" or case_suffix.startswith("passing_excursion-") else None,
            "engineering_crossing_fraction": 0.0 if case_suffix == "within_marked_lane"
            else crossing_fraction}


def control_step(position_xy, forward_xy, velocity_xy_mps, target_xy,
                 *, target_speed_mps=6.0, heading_gain=1.4, speed_gain=0.25):
    """Return bounded throttle/brake/steer requests from Native readbacks.

    The same controller parameters apply to every linked exact case. Requested
    speed is an engineering construction value, not a legal speed threshold.
    """
    points = [tuple(float(value) for value in pair)
              for pair in (position_xy, forward_xy, velocity_xy_mps, target_xy)]
    if any(len(pair) != 2 or not all(isfinite(value) for value in pair)
           for pair in points):
        raise ValueError("Invalid Native controller readback")
    position, forward, velocity, target = points
    if not (isfinite(target_speed_mps) and target_speed_mps > 0 and
            isfinite(heading_gain) and heading_gain > 0 and
            isfinite(speed_gain) and speed_gain > 0):
        raise ValueError("Invalid engineering controller gains")
    bearing = atan2(target[1] - position[1], target[0] - position[0])
    heading = atan2(forward[1], forward[0])
    if hypot(*forward) <= 0 or hypot(target[0] - position[0],
                                     target[1] - position[1]) <= 0:
        raise ValueError("Controller heading or target undefined")
    angle = (bearing - heading + pi) % (2 * pi) - pi
    steer = max(-1.0, min(1.0, heading_gain * angle / (pi / 2)))
    speed = hypot(*velocity)
    speed_error = target_speed_mps - speed
    return {"steer": steer,
            "throttle": max(0.0, min(1.0, speed_gain * speed_error)),
            "brake": max(0.0, min(1.0, -speed_gain * speed_error))}

"""Four synchronized original RGB source streams for marked-lane cases."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown lane source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior lane camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original lane camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Lane source encoder failed")


class LaneCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named lane source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original lane camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original lane camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Lane source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original lane source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original lane camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Measure original marked-lane rows; no geometric or legal tolerance is added."""

from __future__ import annotations

import json
from pathlib import Path

from lane_footprint import measure_footprint


def _center(corners):
    if len(corners) != 4:
        raise ValueError("Native participant body corners missing")
    return (sum(float(point[0]) for point in corners) / 4,
            sum(float(point[1]) for point in corners) / 4)


def measure_saved_sources(source_path, *, expected_ego_id, require_overtaken=False):
    path = Path(source_path)
    if not path.is_file():
        raise ValueError("Original marked-lane source missing")
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines:
        raise ValueError("Original marked-lane source empty")
    result = []
    prior = None
    participant_id = None
    for line in lines:
        row = json.loads(line)
        frame, time_s = row["frame"], row["time_s"]
        if type(frame) is not int or type(time_s) not in (int, float):
            raise ValueError("Invalid original frame identity")
        if prior is not None and (frame != prior[0] + 1 or time_s <= prior[1]):
            raise ValueError("Missing or unordered original lane frame")
        if row["ego_id"] != expected_ego_id:
            raise ValueError("Ego Native identity changed")
        if require_overtaken and row.get("overtaken_id") is None:
            raise ValueError("Passing participant source missing")
        if participant_id is None:
            participant_id = row.get("overtaken_id")
        elif row.get("overtaken_id") != participant_id:
            raise ValueError("Passing participant Native identity changed")
        lane = row["lane"]
        if not lane.get("left_marking") or not lane.get("right_marking"):
            raise ValueError("Native lane marking source missing")
        measured = measure_footprint(lane["polygon_xy_m"], row["ego_corners_xy_m"])
        longitudinal_gap = None
        if row.get("overtaken_id") is not None:
            heading = lane["lane_heading_xy"]
            if len(heading) != 2:
                raise ValueError("Native lane heading missing")
            ego_center = _center(row["ego_corners_xy_m"])
            other_center = _center(row["overtaken_corners_xy_m"])
            longitudinal_gap = sum((ego_center[i] - other_center[i]) * float(heading[i])
                                   for i in range(2))
        result.append({"frame": frame, "time_s": time_s,
                       "road_id": lane["road_id"], "lane_id": lane["lane_id"],
                       "left_marking": lane["left_marking"],
                       "right_marking": lane["right_marking"],
                       "overtaken_id": row.get("overtaken_id"),
                       "ego_light_state": row.get("ego_light_state"),
                       "ego_minus_other_longitudinal_m": longitudinal_gap,
                       "minimum_corner_clearance_m": measured["minimum_corner_clearance_m"],
                       "boundary_crossing": measured["boundary_crossing"],
                       "full_footprint_inside": measured["full_footprint_inside"]})
        prior = frame, time_s
    gaps = [frame["ego_minus_other_longitudinal_m"] for frame in result
            if frame["ego_minus_other_longitudinal_m"] is not None]
    behind_seen = False
    order_reversal = False
    for gap in gaps:
        if gap < 0:
            behind_seen = True
        elif gap > 0 and behind_seen:
            order_reversal = True
    return {"source": str(path), "ego_id": expected_ego_id,
            "overtaken_id": participant_id, "frames": result,
            "measured_order_reversal": order_reversal}

"""Value-free footprint geometry for a recorded marked traffic lane.

The caller supplies native lane boundary vertices and measured vehicle corners
from the same frame. This module does not decide lawful lane use or exceptions.
"""

from __future__ import annotations

from math import hypot, isfinite


def _point(value):
    if len(value) != 2 or not all(isfinite(float(v)) for v in value):
        raise ValueError("Expected finite two-dimensional coordinates")
    return float(value[0]), float(value[1])


def _cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _distance_to_segment(p, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    norm = dx * dx + dy * dy
    if norm == 0:
        raise ValueError("Coincident boundary vertices")
    t = max(0.0, min(1.0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / norm))
    return hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy)


def _inside(p, polygon):
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
                inside = not inside
    return inside


def _strict_intersection(a, b, c, d):
    return _cross(a, b, c) * _cross(a, b, d) < 0 and _cross(c, d, a) * _cross(c, d, b) < 0


def measure_footprint(lane_polygon, body_corners):
    """Return signed minimum corner clearance and full-body containment.

    Positive clearance means every measured body corner is inside. Zero means
    boundary contact. Negative means at least one corner is outside. Segment
    crossings are checked separately so a concave lane cannot hide an excursion.
    Values are physical distances in the coordinate system supplied by capture.
    """
    lane = [_point(v) for v in lane_polygon]
    body = [_point(v) for v in body_corners]
    if len(lane) < 3 or len(body) != 4:
        raise ValueError("Need a lane polygon and four vehicle body corners")
    lane_edges = list(zip(lane, lane[1:] + lane[:1]))
    body_edges = list(zip(body, body[1:] + body[:1]))
    if any(a == b for a, b in lane_edges + body_edges):
        raise ValueError("Degenerate geometry")
    signed = []
    for corner in body:
        distance = min(_distance_to_segment(corner, a, b) for a, b in lane_edges)
        signed.append(distance if _inside(corner, lane) else -distance)
    crosses = any(_strict_intersection(a, b, c, d) for a, b in body_edges for c, d in lane_edges)
    clearance = min(signed)
    return {
        "minimum_corner_clearance_m": clearance,
        "corner_clearances_m": signed,
        "boundary_crossing": crosses,
        "all_corners_inside": all(value > 0 for value in signed),
        "full_footprint_inside": all(value > 0 for value in signed) and not crosses,
    }

"""Independent saved source and complete camera audit for C147331 cases.

This checks software evidence only. Physical visibility, municipal applicability,
lawful passing and actual completion remain for independent local review.
"""

from __future__ import annotations

import argparse
from hashlib import sha256
import json
from pathlib import Path

from lane_finalizer import analyze


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
SOURCES = ("video_frames.jsonl", "trace.jsonl", "marked_lane_sources.jsonl")


def digest(path):
    return sha256(Path(path).read_bytes()).hexdigest()


def audit_attempt(attempt, report, *, decoder=None, receipt_dir=None):
    root = Path(attempt)
    report = json.loads(Path(report).read_text()) if not isinstance(report, dict) else report
    for name in (*SOURCES, "config.json"):
        if not (root / name).is_file():
            raise ValueError("Missing audited original lane source: " + name)
    sources = report["measurements"]["lane_boundary_observation"]["sources"]
    if set(sources) != set(SOURCES):
        raise ValueError("Lane analysis source inventory differs")
    if any(digest(root / name) != expected for name, expected in sources.items()):
        raise ValueError("Lane analysis source hash differs")
    independent = analyze(root, write_channel=False)
    if independent["case_id"] != report["case_id"] or independent["measurements"] != report["measurements"]:
        raise ValueError("Lane analysis differs from recomputed original sources")
    mapping = [json.loads(line) for line in (root / "video_frames.jsonl").read_text().splitlines()]
    if not mapping:
        raise ValueError("No original lane frames")
    if decoder is None:
        from worker_exchange.media import audit as decoder
    if receipt_dir is not None:
        Path(receipt_dir).mkdir(parents=True, exist_ok=False)
    camera_receipts = {}
    for name in CAMERAS:
        source = root / (name + ".mkv")
        if not source.is_file():
            raise ValueError("Missing named lane source camera: " + name)
        receipt = None if receipt_dir is None else Path(receipt_dir) / (name + "-decode.json")
        decoded = decoder(source, len(mapping),
                          mapping_sha256=digest(root / "video_frames.jsonl"), receipt=receipt)
        if decoded.get("frames") != len(mapping):
            raise ValueError("Named lane camera frame count differs: " + name)
        camera_receipts[name] = {"source_sha256": digest(source), "decode": decoded}
    return {"format": "worker-lane-source-audit", "case_id": report["case_id"],
            "source_hashes": sources, "frame_count": len(mapping),
            "camera_decodes": camera_receipts,
            "measurement_recomputed": True, "physical_visibility_claimed": False,
            "legal_acceptance_claimed": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--analysis", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    output = Path(args.output)
    if output.exists():
        raise ValueError("Retain previous lane audit")
    receipt = audit_attempt(args.attempt, args.analysis,
                            receipt_dir=output.parent / (output.stem + "-decodes"))
    output.write_text(json.dumps(receipt, indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()
